import { getOrders } from '../api/orders';
import { loadDashboard } from './dashboard';

jest.mock('../api/orders'); // troca todas as funções do módulo por jest.fn()

const mockedGetOrders = jest.mocked(getOrders);

afterEach(() => jest.clearAllMocks());

test('soma o total dos pedidos', async () => {
  mockedGetOrders.mockResolvedValue([
    { id: '1', total: 30 },
    { id: '2', total: 12.5 },
  ]);

  const dashboard = await loadDashboard('loja-1');

  expect(mockedGetOrders).toHaveBeenCalledWith('loja-1');
  expect(dashboard.revenue).toBe(42.5);
});

import { act, renderHook } from '@testing-library/react-native';
import { useDebounce } from './useDebounce';

beforeEach(() => jest.useFakeTimers());
afterEach(() => jest.useRealTimers());

test('só atualiza depois de 300 ms sem mudanças', async () => {
  const { result, rerender } = await renderHook(({ value }) => useDebounce(value, 300), {
    initialProps: { value: 'p' },
  });

  await rerender({ value: 'pizza' });
  expect(result.current).toBe('p'); // ainda o valor antigo

  await act(async () => {
    jest.advanceTimersByTime(300); // o tempo passa na hora, sem esperar de verdade
  });
  expect(result.current).toBe('pizza');
});

import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { LoginForm } from './LoginForm';

test('envia e-mail e senha', async () => {
  const user = userEvent.setup();
  const onSubmit = jest.fn();
  render(<LoginForm onSubmit={onSubmit} />);

  await user.type(screen.getByRole('textbox', { name: 'E-mail' }), 'ana@exemplo.com');
  await user.type(screen.getByLabelText('Senha'), '123456');
  await user.click(screen.getByRole('button', { name: 'Entrar' }));

  expect(onSubmit).toHaveBeenCalledWith({ email: 'ana@exemplo.com', password: '123456' });
});

test('mostra erro com e-mail vazio', async () => {
  const user = userEvent.setup();
  render(<LoginForm onSubmit={jest.fn()} />);

  await user.click(screen.getByRole('button', { name: 'Entrar' }));

  expect(screen.getByRole('alert')).toHaveTextContent('Informe o e-mail');
});

import { render, screen, userEvent } from '@testing-library/react-native';
import { MenuScreen } from './MenuScreen';

test('lista os pratos e adiciona ao carrinho', async () => {
  const user = userEvent.setup();
  await render(<MenuScreen />); // await funciona com render síncrono (v13) e assíncrono (v14)

  // findBy espera o item aparecer depois da busca na API
  const pizza = await screen.findByText('Pizza margherita');
  expect(pizza).toBeOnTheScreen();

  await user.press(screen.getByRole('button', { name: 'Adicionar Pizza margherita' }));

  expect(screen.getByText('1 item no carrinho')).toBeOnTheScreen();
  expect(screen.queryByText('Carrinho vazio')).not.toBeOnTheScreen();
});

import { http, HttpResponse } from 'msw';
import { setupServer } from 'msw/node';

const server = setupServer(
  http.get('https://api.example.com/menu', () =>
    HttpResponse.json([{ id: 'p1', name: 'Pizza margherita', price: 42 }]),
  ),
);

beforeAll(() => server.listen({ onUnhandledRequest: 'error' }));
afterEach(() => server.resetHandlers()); // desfaz os server.use de cada teste
afterAll(() => server.close());

test('mostra mensagem quando a API falha', async () => {
  server.use(
    http.get('https://api.example.com/menu', () => new HttpResponse(null, { status: 500 })),
  );
  await render(<MenuScreen />);

  expect(await screen.findByText('Não foi possível carregar o cardápio')).toBeOnTheScreen();
});

import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { renderHook, waitFor } from '@testing-library/react-native';
import type { ReactNode } from 'react';
import { useOrders } from './useOrders';

function createWrapper() {
  // Um client novo por teste: o cache de um teste não vaza para o outro
  const queryClient = new QueryClient({ defaultOptions: { queries: { retry: false } } });
  return ({ children }: { children: ReactNode }) => (
    <QueryClientProvider client={queryClient}>{children}</QueryClientProvider>
  );
}

test('carrega os pedidos', async () => {
  const { result } = await renderHook(() => useOrders(), { wrapper: createWrapper() });

  await waitFor(() => expect(result.current.isSuccess).toBe(true));
  expect(result.current.data).toHaveLength(2); // resposta vinda do handler do MSW
});
